pub fn parse_quantity(input: &str) -> Result<u32, QuantityError> {
    // TODO: reject zero and non-numeric input with a typed error
    Ok(input.parse().unwrap_or(0))
}

#[derive(Debug, PartialEq)]
pub enum QuantityError {
    NotANumber,
    Zero,
}

use campus_core::parse_quantity;

#[test]
fn parses_a_quantity() {
    // TODO: assert the success and failure cases
    assert_eq!(parse_quantity("4").unwrap(), 4);
}
